var palette;
var objects = [];
var gridView = false, gs, gx, gy, grid;

function setup() {
	createCanvas(windowWidth, windowHeight);
	describe("Packing Circles into a Rectangle or vice versa. Objects no overlapping each other, just complete inside or between others.");
	pixelDensity(1);
	frameRate(30);
	background("beige");
	palette = [
		// https://coolors.co/palette/335c67-fff3b0-e09f3e-9e2a2b-540b0e
		["#335c67", "#fff3b0", "#e09f3e", "#9e2a2b", "#540b0e"], 
		// https://coolors.co/palette/ffffff-84dcc6-a5ffd6-ffa69e-ff686b
		["#84dcc6", "#a5ffd6"],
		["#ffa69e", "#ff686b"],
		// https://coolors.co/palette/50514-f25f5c-ffe066-247ba0-70c1b3
		["#50514", "#f25f5c", "#ffe066", "#247ba0", "#70c1b3"],
		["#3B434F", "#94A6AE", "#0f478c"]
	];

	objects = [];
	objects.push(new GrObj());

	// variables for grid usage
	gs = floor(max(width, height) / 3);
	gx = floor(width / gs);
	gy = floor(height / gs);
	grid = [];
	for (y = gs * 0.5; y < height; y += gs) {
		for (x = gs * 0.5; x < width; x += gs) {
			grid.push(new GrObj(x, y, gs));
		}
	}
}

function mouseClicked() {
	if (mouseButton === LEFT) {
		gridView = !gridView;
		// objects.push(new GrObj((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), max(width, height) * random(0.3, 0.5)));
	}
}

function windowResized() {
	setup();
}

function draw() {
	// blendModebackground(255); // ("beige");

	if (gridView) {
		for (y = gs * 0.5, gi = 0; y < height; y += gs) {
			for (x = gs * 0.5; x < width; x += gs, gi++) {
				if (!grid[gi].alive) grid[gi] = new GrObj(x, y, gs);
				grid[gi].update();
				grid[gi].show();
			}
		}		
	}

	if (!gridView) {
		// create object, if empty
		if (objects.length === 0) objects.push(new GrObj());

		objects = objects.filter((x) => x.alive);
		for (o of objects) {
			o.update();
			o.show();
		}
	}

	if (false) {
		noStroke();
		fill(0)
		text(""+objects.length, 0, 10);
		for (i = 0; i < objects.length; i++) text(""+objects[i].childs.length, 0, 20+i*10);
	}
}


/*******************************************************************************************
 * Class GrObj: 2 types 
 */

class GrObj {
	constructor(x, y, s) {
		// position
		this.x = x || random(width * 0.45, width * 0.55); // random(-width * 0.1, width * 1.1);
		this.y = y || random(height * 0.45, height * 0.55); // random(-height * 0.1, height * 1.1);
		this.pos = createVector(this.x, this.y);

		// type and childs
		this.type = random() < 0.5 ? 1 : 2; // 1 = circle (of squares), 2 = square (od circles)
		this.size = s || max(width, height) * random(0.5, 0.7); // size 1/3 with some variations, rect has to be doubled
		this.childs = [];
		this.maxChildSize = this.size * 0.5 * 0.3;
		this.minSize = 10;

		// colors and life time
		this.clrs = random(palette);
		this.blendMode = random() < 0.5 ? BLEND : DIFFERENCE;
		this.time = millis(); // creation time
		this.ttl = random(10, 30) * 1000 + this.time; // seconds of lifetime
		this.alive = true; // after ttl stioll alive, till all childs removed
	}

	update() {
		if (millis() > this.ttl) {
			// remove child
			if (this.childs.length > 0) {
				this.childs.pop(); // remove last element
			}
			if (this.childs.length === 0) this.alive = false;

		} else {
			this.maxChildSize -= 0.25;
			if (this.maxChildSize < this.minSize) {
				this.ttl = millis(); // end child generation
				return;
			}

			// addChilds
			switch(this.type) {
				case 1:
					// circle (of squares)
					this.addToCircle();
					break;

				case 2:
					// square (od circles)
					this.addToSquare();
					break;

				default:
					console.error("GrObj.show(): type does not exists " + this.type);
			}
		}
	}

	addToCircle() {
		// create square in circle
		for (i = 0; i < 50; i++) { // try x times to insert, when succesful, break out
			const size_h = this.size * 0.5;
			const pos = p5.Vector.random2D().mult(random(this.minSize, size_h));
			const x = this.x + pos.x;
			const y = this.y + pos.y;
			const s = random(this.maxChildSize * 0.5, this.maxChildSize);
			const s_2 = s * 0.5;
			// look edges
			const p1 = createVector(x + s_2, y + s_2);
			const p2 = createVector(x - s_2, y + s_2);
			const p3 = createVector(x + s_2, y - s_2);
			const p4 = createVector(x - s_2, y - s_2);
			// only insert, wehen square is in circle
			if (this.pos.dist(p1) < size_h && this.pos.dist(p2) < size_h && 
					this.pos.dist(p3) < size_h && this.pos.dist(p4) < size_h) {
				// test if no overlapping, only inside or outside
				const candidate = {x, y, s};
				let okToInsert = true;
				for (c of this.childs) {
					okToInsert = okToInsert && this.checkNoOverlapRects(candidate, c);
				}
				if (okToInsert) {
					const c = random(this.clrs);
					this.childs.push({x, y, s, c});
					return; // break out when child added
				}
			}
		} // try hard to insert an child
	}
	checkNoOverlapRects (r1, r2) {
		// true, when no partly overlappig, only complete outside or inside
		const r1sh = r1.s * 0.5;
		const r2sh = r2.s * 0.5;

		// inside
		let completeInside = 
				(r1.x - r1sh > r2.x - r2sh) && 
				(r1.x + r1sh < r2.x + r2sh) &&
				(r1.y - r1sh > r2.y - r2sh) && 
				(r1.y + r1sh < r2.y + r2sh);

		// outside
		let completeOutside = 
				((r1.x - r1sh < r2.x - r2sh) && (r1.x + r1sh < r2.x - r2sh)) ||
				((r1.x - r1sh > r2.x + r2sh) && (r1.x + r1sh > r2.x + r2sh)) ||
				((r1.y - r1sh < r2.y - r2sh) && (r1.y + r1sh < r2.y - r2sh)) ||
				((r1.y - r1sh > r2.y + r2sh) && (r1.y + r1sh > r2.y + r2sh))

		return completeInside || completeOutside;
	}

	addToSquare() {
		// create circle in square
		for (i = 0; i < 50; i++) { // try x times to insert, when succesful, break out
			var size_h = this.size * 0.5;
			var s = random(this.maxChildSize * 0.5, this.maxChildSize);
			const s2 = s * 0.5;
			var x = random(this.x - size_h - s2, this.x + size_h + s2);
			var y = random(this.y - size_h - s2, this.y + size_h + s2);
			var c = random(this.clrs);
			// check if inside the rect
			if (this.x - size_h < x - s2 && this.x + size_h > x + s2 &&
					this.y - size_h < y - s2 && this.y + size_h > y + s2) {
				// test if no overlapping, only inside or outside
				var candidate = {x, y, s};
				var okToInsert = true;
				for (c of this.childs) {
					okToInsert = okToInsert && this.checkNoOverlapCircles(candidate, c);
				}
				if (okToInsert) {
					var c = random(this.clrs);
					this.childs.push({x, y, s, c});
					return; // break out when child added
				}
			}
		} // try hard to insert that circle
	}
	checkNoOverlapCircles (c1, c2) {
		const distance = dist(c1.x, c1.y, c2.x, c2.y);
		return distance > (c1.s + c2.s) * 0.5 || distance < (c2.s - c1.s) * 0.45; // 0.5 would be enough, but some space
	}

	show() {
		push();
		blendMode(this.blendMode)

		switch(this.type) {
			case 1:
				// circle (of squares)
				this.showCircle();
				break;

			case 2:
				// square (od circles)
				this.showSquare();
				break;

			default:
    		console.error("GrObj.show(): type does not exists " + this.type);
		}

		pop();
	}

	showCircle() {
		push();

		rectMode(CENTER);
		noStroke()
		for (child of this.childs) {
			fill(child.c);
			rect(child.x, child.y, child.s);
		}

		pop();
	}

	showSquare() {
		push();

		noStroke()
		for (child of this.childs) {
			fill(child.c);
			circle(child.x, child.y, child.s);
		}

		pop();
	}
}
